class Solution:
    def budgetPair(self, prices: List[int], budget: int) -> List[int]:
        for i in range(len(prices)):
            for j in range(i + 1, len(prices)):
                if prices[i] + prices[j] == budget:
                    return [i, j]
        return [-1, -1]

