class Solution {
    public int[] budgetPair(int[] prices, int budget) {
        Map<Long, Integer> seen = new HashMap<>();
        for (int j = 0; j < prices.length; j++) {
            Integer i = seen.get((long) budget - prices[j]);
            if (i != null) return new int[] {i, j};
            seen.put((long) prices[j], j);
        }
        return new int[] {-1, -1};
    }
}

