class Solution {
    public int[] budgetPair(int[] prices, int budget) {
        int i = 0, j = prices.length - 1;
        while (i < j) {
            long s = (long) prices[i] + prices[j];
            if (s == budget) return new int[] {i, j};
            if (s < budget) i++;
            else j--;
        }
        return new int[] {-1, -1};
    }
}

